"""Read-only v5 interpretation audit of cached v4 results."""
import csv,hashlib,json
from pathlib import Path
import numpy as np,pandas as pd
from src.chapman_evaluate_v4 import manifests
ROOT=Path(__file__).resolve().parents[1]; V4=ROOT/'outputs/phase1_chapman_seed1_v4'; OUT=ROOT/'outputs/phase1_interpretation_audit_v5'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1<<20),b''):h.update(b)
 return h.hexdigest()
def write(name,text): (OUT/name).write_text(text,encoding='utf-8')
def main():
 OUT.mkdir(exist_ok=True); a,f,d=manifests(); metrics=pd.read_csv(V4/'all_condition_metrics_v4.csv'); twa=metrics[metrics.label=='TWA'].copy(); clean=float(twa[twa.condition=='clean'].auprc.iloc[0]); v=float(twa[twa.condition=='V1_V4'].auprc.iloc[0]); ind=twa[twa.condition.str.startswith('independent_')].copy(); ind['loss']=clean-ind.auprc; other=ind[ind.condition!='independent_2_3_4_5']; meanother=float(other.auprc.mean()); rank=int(ind.auprc.rank(ascending=True,method='min')[ind.condition=='independent_2_3_4_5'].iloc[0]); boot=pd.read_csv(V4/'bootstrap_summary_v4.csv').set_index('label');
 rows=[]; groups={}
 names=['I','II','V1','V2','V3','V4','V5','V6']; display=['I','II','III','aVR','aVL','aVF','V1','V2','V3','V4','V5','V6']
 for q in f:
  n='independent_'+'_'.join(map(str,q)); p=V4/'test_predictions_v4'/f'{n}.npz'; digest=sha(p); groups.setdefault(digest,[]).append(n); u=[names[i] for i in q]; affected=display[:6] if ({0,1}&set(q)) else []; affected+=['V'+str(i-1) for i in q if i>=2]; rows.append({'condition':n,'prediction_sha256':digest,'affected_independent_measurements':';'.join(u),'unavailable_displayed_leads':';'.join(affected)})
 for i,r in enumerate(rows): r['equivalence_group_id']='eq%02d'%(sorted(groups).index(r['prediction_sha256'])+1);r['group_size']=len(groups[r['prediction_sha256']])
 pd.DataFrame(rows).to_csv(OUT/'PHYSICAL_CONDITION_EQUIVALENCE.csv',index=False); pd.DataFrame(rows).to_csv(OUT/'MATCHED_COMPARATOR_AUDIT.csv',index=False)
 disp=twa[twa.condition.str.startswith('displaymask_')].copy(); disp['loss']=clean-disp.auprc
 rev=twa[twa.condition.str.contains('reversal')].copy();rev['loss']=clean-rev.auprc
 summary={'clean_twa_auprc':clean,'v1_v4_twa_auprc':v,'v1_v4_absolute_loss':clean-v,'mean_other69_auprc':meanother,'v1_v4_rank_worst_to_best_among_70':rank,'signed_primary_contrast':float(boot.loc['TWA','mean_effect']),'primary_ci95':[float(boot.loc['TWA','low95']),float(boot.loc['TWA','high95'])],'sb_contrast':float(boot.loc['SB','mean_effect']),'stach_contrast':float(boot.loc['STach','mean_effect']),'nominal_independent_masks':70,'unique_prediction_outcomes':len(groups),'independent_mean_auprc':float(ind.auprc.mean()),'independent_median_auprc':float(ind.auprc.median()),'independent_unique_mean_auprc':float(pd.DataFrame(rows).merge(ind[['condition','auprc']],on='condition').groupby('prediction_sha256').auprc.first().mean()),'display_mean_auprc':float(disp.auprc.mean()),'display_median_auprc':float(disp.auprc.median()),'independent_fraction_loss_ge_005':float((ind.loss>=.05).mean()),'display_fraction_loss_ge_005':float((disp.loss>=.05).mean()),'worst10_independent':ind.nsmallest(10,'auprc')[['condition','auprc','loss']].to_dict('records'),'worst10_display':disp.nsmallest(10,'auprc')[['condition','auprc','loss']].to_dict('records'),'terminal_reversal_losses':rev[['condition','auprc','loss']].to_dict('records'),'status':'MIXED_SIGNAL_REQUIRES_NEW_CONFIRMATORY_PROTOCOL'}
 (OUT/'CORRECTED_RESULT_SUMMARY.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
 write('GATE_IMPLEMENTATION_AUDIT.md',f'''# Gate implementation audit\n\nThe frozen primary estimand was `(clean − V1V4) − (clean − mean_other69)`. Its observed signed value is {summary['signed_primary_contrast']:.6f} (95% CI {summary['primary_ci95'][0]:.6f} to {summary['primary_ci95'][1]:.6f}). Negative means V1–V4 was **less damaging** than the mean of the other 69 masks.\n\nThe v4 implementation used `abs(primary_effect) >= 0.05`, accepting a significant contrast in either direction. It therefore did not enforce a prespecified positive direction and did not directly verify that one particular physical scenario itself had AUPRC loss ≥0.05 with its own synchronized interval. The automatic `PROCEED_MULTISEED` result is not a valid frozen confirmation decision.\n''')
 write('PHYSICS_SEMANTICS_AUDIT.md','''# Physics semantics audit\n\n`transform()` reconstructs displayed leads from the eight independent measurements. If I or II is unavailable, all six limb displays are assigned the train-normalized sentinel because those derived displays are not identifiable from the remaining independent signal under the frozen adapter. This is a conservative information-availability abstraction, not a literal electrode-disconnection waveform model. Hence masks containing I or II can be prediction-equivalent when their remaining available chest information is the same.\n\nFour unavailable independent measurements and four unavailable displayed leads are not severity-matched: losing I or II removes six displayed limb outputs, whereas a display mask removes exactly four model channels. Exact terminal cable reversals and derived lead algebra are reconstructible from a clean conventional 12-lead recording. Open-circuit impedance, motion artefact, and physical electrode displacement are not; the unavailable-lead sentinel is only an abstraction.\n''')
 write('RECOMMENDED_CONFIRMATORY_DESIGN.md','''# Recommended confirmatory design (draft only)\n\nQuestion: Do conventional independent displayed-lead masking evaluations underestimate ECG classifier failures caused by electrically coupled acquisition faults and terminal reversals?\n\nUse Chapman only as exploratory/development evidence and leave Ningbo untouched for confirmation. Distinguish displayed leads, independent measurements, electrodes, and terminal reversals. Collapse prediction-equivalent consequence classes before analysis; compare severity- or consequence-matched conditions; prespecify a positive direction; and compute scenario-level synchronized 1,000-replicate intervals. Retain T-wave abnormality primary and SB/STach negative controls. Require at least three fixed seeds, a Ningbo confirmation effect in the same direction, no equal-or-larger loss in both controls, and a predeclared effect threshold. Before authorizing, benchmark cached inference and reserve roughly 3× the observed single-seed GPU time plus 20 GB storage for data, checkpoints, and prediction caches.\n''')
 write('FINAL_INTERPRETATION_DECISION.md','''# MIXED_SIGNAL_REQUIRES_NEW_CONFIRMATORY_PROTOCOL\n\nThe v4 data show substantial variation across nominal masks, but V1–V4 was less damaging than the average comparator mask, not more damaging. Because nominal independent masks include prediction-equivalent availability abstractions and the v4 gate used an absolute signed contrast, the result cannot confirm the proposed mechanism or justify multiseed work as frozen. A new, directionally specified, severity-matched confirmatory protocol is required.\n''')
if __name__=='__main__':main()
